package com.stellasora.viethoa.localadb;
import android.content.*;import android.net.nsd.*;import android.net.wifi.WifiManager;import android.os.*;
/** Same-device mDNS discovery; no remote host is accepted. */
final class PairingDiscovery implements AutoCloseable {
 interface Callback{void found(String host,int port);void failed(String message);}
 private final NsdManager manager;private final Handler main=new Handler(Looper.getMainLooper());private final Callback callback;private final String type;private NsdManager.DiscoveryListener listener;private WifiManager.MulticastLock lock;private volatile boolean closed,resolving;private Runnable timeout;
 PairingDiscovery(Context context,String serviceType,Callback cb){manager=(NsdManager)context.getSystemService(Context.NSD_SERVICE);type=serviceType;callback=cb;try{WifiManager wifi=(WifiManager)context.getApplicationContext().getSystemService(Context.WIFI_SERVICE);lock=wifi.createMulticastLock("StellaSora-mDNS");lock.setReferenceCounted(false);lock.acquire();}catch(Exception ignored){}}
 void start(){listener=new NsdManager.DiscoveryListener(){public void onDiscoveryStarted(String t){}public void onDiscoveryStopped(String t){}public void onStopDiscoveryFailed(String t,int e){}public void onServiceLost(NsdServiceInfo s){}public void onStartDiscoveryFailed(String t,int e){if(!closed)callback.failed("Không dò được cổng mDNS. Có thể nhập cổng thủ công.");close();}public void onServiceFound(NsdServiceInfo service){if(closed||resolving)return;resolving=true;try{manager.resolveService(service,new NsdManager.ResolveListener(){public void onResolveFailed(NsdServiceInfo s,int e){resolving=false;}public void onServiceResolved(NsdServiceInfo s){resolving=false;if(closed||s.getHost()==null)return;try{String host=AdbClient.ownHost(s.getHost().getHostAddress());int port=AdbClient.port(s.getPort());callback.found(host,port);}catch(Exception ignored){}}});}catch(Exception e){resolving=false;}}};try{manager.discoverServices(type,NsdManager.PROTOCOL_DNS_SD,listener);timeout=()->{if(!closed)callback.failed("Chưa tìm thấy cổng trong 60 giây. Hãy mở đúng màn hình Gỡ lỗi không dây hoặc nhập cổng thủ công.");close();};main.postDelayed(timeout,60000);}catch(Exception e){callback.failed("Không dùng được mDNS. Hãy nhập cổng thủ công.");close();}}
 @Override public void close(){if(closed)return;closed=true;if(timeout!=null)main.removeCallbacks(timeout);if(listener!=null)try{manager.stopServiceDiscovery(listener);}catch(Exception ignored){}if(lock!=null&&lock.isHeld())lock.release();}
}
